/**
 * Records a response captured by the portal scraper bot. The bot may
optionally include the full message body (`rawContent`), the message
`subject`, and the portal sender's `senderEmail` / `senderName` so
reviewers can read the original payor message in the UI.

 * @summary Record a response from the portal
 */
export const RecordPortalResponseBody = zod.object({
  submissionId: zod.number(),
  responseType: zod.enum([
    "approval",
    "denial",
    "partial_approval",
    "info_request",
    "acknowledgment",
    "other",
  ]),
  content: zod
    .string()
    .optional()
    .describe("Short preview \/ summary of the portal response."),
  rawContent: zod
    .string()
    .optional()
    .describe(
      "Full body of the portal response, preserved verbatim for display.",
    ),
  bodyFormat: zod
    .enum(["html", "text"])
    .optional()
    .describe(
      "Declares whether `rawContent`\/`content` is HTML or plain text. When\n`html`, the UI renders the response through a sanitizer so links,\nemphasis, and lists survive. Defaults to `text` for backwards\ncompatibility with bots that have not been updated.\n",
    ),
  subject: zod
    .string()
    .optional()
    .describe("Optional subject \/ title of the portal message."),
  senderEmail: zod
    .string()
    .optional()
    .describe(
      "Optional email address of the portal user that posted the response.",
    ),
  senderName: zod
    .string()
    .optional()
    .describe(
      "Optional display name of the portal user that posted the response.",
    ),
  metadata: zod.object({}).passthrough().optional(),
});

export const RecordPortalResponseResponse = zod.object({
  responseId: zod.number().optional(),
  claimId: zod.number().optional(),
});

